(function(){'use strict';window.showToast=window.LSM.showToast;window.escapeHtml=window.LSM.escapeHtml;window.escapeJs=window.LSM.escapeJs;window.ensureCsrfToken=window.LSM.ensureCsrfToken;window.formatDate=window.LSM.formatDate;window.isAdmin=window.LSM.isAdmin;function showHtmxAlert(evt){var el=evt.detail.elt;if(!el)return;var status=evt.detail.xhr?evt.detail.xhr.status:0;if(!(el.matches('form')||el.matches('[hx-post]')||el.matches('[hx-put]')||el.matches('[hx-delete]'))){return;}
if(status>=200&&status<300){if(el.dataset&&el.dataset.toast){window.LSM.showToast(el.dataset.toast,'success');}}else if(status>=400){try{var data=JSON.parse(evt.detail.xhr.responseText);window.LSM.showToast(data.detail||'操作失败','error');}catch(e){window.LSM.showToast('操作失败 ('+status+')','error');}}}
function initHtmxGlue(){document.body.addEventListener('htmx:configRequest',function(evt){evt.detail.headers['HX-Request']='true';var verb=(evt.detail.verb||'').toUpperCase();if(window.__csrf_token&&verb!=='GET'){evt.detail.headers['X-CSRF-Token']=window.__csrf_token;}});document.body.addEventListener('htmx:responseError',function(evt){if(evt.detail.xhr&&evt.detail.xhr.status===401){window.location.href='/login';}});document.body.addEventListener('htmx:afterSwap',function(evt){showHtmxAlert(evt);});document.body.addEventListener('htmx:afterRequest',function(evt){if(evt.detail.pathInfo&&evt.detail.pathInfo.requestPath==='/api/auth/login'&&evt.detail.successful){window.LSM.ensureCsrfToken(true);}});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initHtmxGlue);}else{initHtmxGlue();}
document.addEventListener('DOMContentLoaded',function(){if(localStorage.getItem('encrypt_key_dismissed'))return;fetch('/api/auth/encrypt-key-status',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){if(!data.has_custom_key){showEncryptKeyBanner();}}).catch(function(){});});function showEncryptKeyBanner(){var content=document.querySelector('.content-body');if(!content)return;var banner=document.createElement('div');banner.id='encrypt-key-banner';banner.className='encrypt-banner';banner.innerHTML='<div class="encrypt-banner-text">'+'<span class="encrypt-banner-icon" aria-hidden="true">🔐</span>'+'<span>系统使用<strong>自动生成的加密密钥</strong>，建议设置自定义环境变量 '+'<code>CONFIG_ENCRYPT_KEY</code> 以增强安全性。'+'<a href="/config">前往配置页</a></span>'+'</div>'+'<button type="button" class="encrypt-banner-close" aria-label="不再提示" title="我知道了，不再提示">✕</button>';banner.querySelector('.encrypt-banner-close').addEventListener('click',dismissEncryptKeyBanner);content.insertBefore(banner,content.firstChild);}
function dismissEncryptKeyBanner(){localStorage.setItem('encrypt_key_dismissed','1');var banner=document.getElementById('encrypt-key-banner');if(banner)banner.remove();}
document.addEventListener('DOMContentLoaded',function(){window.LSM.ensureCsrfToken();});})();